import requests

endpoint = "https://tickets.example.com/mcp"
init = requests.post(endpoint, json={"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {}})
session_id = init.headers["Mcp-Session-Id"]

headers = {"Mcp-Session-Id": session_id, "Authorization": "Bearer sk-example-token"}
call = requests.post(endpoint, headers=headers, json={
    "jsonrpc": "2.0", "id": 2, "method": "tools/call",
    "params": {"name": "create_ticket", "arguments": {"title": "Printer offline"}}
})
print(call.json())
